import json
from itertools import product

reps = ["Kim", "Mahr", "Parra", "Quinn", "Stuckey", "Tiao", "Udall"]
opts = {"A": ("Kim", 2), "B": ("Mahr", 1), "C": ("Parra", 3),
        "D": ("Stuckey", 2), "E": ("Tiao", 1)}

def valid(a):
    if (a["Parra"] == 1) == (a["Tiao"] == 1):
        return False
    if (a["Tiao"] == 2) == (a["Udall"] == 2):
        return False
    if a["Parra"] != a["Quinn"]:
        return False
    if a["Stuckey"] != a["Udall"]:
        return False
    vals = list(a.values())
    return vals.count(3) > vals.count(2)

sols = []
for combo in product([1, 2, 3], repeat=7):
    a = dict(zip(reps, combo))
    if valid(a) and a["Mahr"] == a["Stuckey"]:
        sols.append(a)

possible = []
for k, (r, z) in opts.items():
    if any(s[r] == z for s in sols):
        possible.append(k)

if len(possible) == 1:
    print(json.dumps({"final_answer": possible[0],
                      "evidence": {"num_solutions": len(sols), "possible": possible}}))
else:
    print("UNSUPPORTED")
